#define PI2 6.28318530718
#define PIhalf 1.57079632679

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     int num_samples = int((iMouse.y / iResolution.y) * float(64)) + 1;
     float sample_angle = PI2 / float(num_samples);
     float blur_length = (iMouse.x / iResolution.x) * 130.0;

     vec4 col;

     vec2 uv;
     float this_angle;
     float tx;
     float ty;

     for(int i = 0; i < num_samples; i++){
         this_angle = (sample_angle * float(i));
         tx = blur_length * sin(PIhalf - this_angle);
         ty = blur_length * sin(this_angle);

         uv = (fragCoord + vec2(tx,ty)) / iResolution.xy;
         col += texture(iChannel0, uv);
     };

     fragColor = col / float(num_samples);
     //fragColor = texture(iChannel0, fragCoord / iResolution.xy);

}
